<?php require 'C:/xampp/htdocs/boticav1/config/database.php';$db=appPdoConnection();$q=$db->query("SELECT e.IdEmpleado,e.Empleado,pp.Sueldo,p.IdPlanilla,p.Periodo,p.Detalle,p.Neto FROM Rhu_Empleado e LEFT JOIN Rhu_PlanillaPersonal pp ON pp.IdEmpleado=e.IdEmpleado LEFT JOIN Rhu_PlanillaPeriodo p ON p.IdEmpleado=e.IdEmpleado WHERE e.DniRuc='73604150'");echo json_encode($q->fetchAll(PDO::FETCH_ASSOC)),"\n";$q=$db->query("SELECT pg.IdPago,pg.IdPlanilla,pg.Tipo,pg.Importe,pg.Anulado,pg.IdCajaBanco FROM Rhu_PlanillaPago pg JOIN Rhu_PlanillaPeriodo p ON p.IdPlanilla=pg.IdPlanilla JOIN Rhu_Empleado e ON e.IdEmpleado=p.IdEmpleado WHERE e.DniRuc='73604150'");echo json_encode($q->fetchAll(PDO::FETCH_ASSOC)),"\n";
